import Groq from 'groq-sdk';
import { OFFLINE_QUESTION_BANK } from '../data/offlineQuestionBank';

export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  correctAnswer: string;
  explanation: string;
}

export interface QuizResponse {
  topic: string;
  level: number;
  // 'ai' when generated by Groq, 'offline' when served from the curated bank
  source: 'ai' | 'offline';
  questions: QuizQuestion[];
}

// Thrown when AI generation fails and no curated questions exist for the topic.
export class QuizUnavailableError extends Error {}

// Models are tried in order. Override with GROQ_MODEL (comma-separated list).
const DEFAULT_MODELS = ['openai/gpt-oss-120b', 'openai/gpt-oss-20b'];

const getModels = (): string[] => {
  const configured = (process.env.GROQ_MODEL || '')
    .split(',')
    .map((m) => m.trim())
    .filter(Boolean);
  return configured.length ? configured : DEFAULT_MODELS;
};

const shuffle = <T>(items: T[]): T[] => {
  const copy = [...items];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
};

const findBankTopic = (topic: string): string | undefined => {
  const wanted = topic.trim().toLowerCase();
  return Object.keys(OFFLINE_QUESTION_BANK).find((t) => t.toLowerCase() === wanted);
};

const getOfflineQuestions = (topic: string): QuizQuestion[] => {
  const bankTopic = findBankTopic(topic);
  if (!bankTopic) {
    throw new QuizUnavailableError(
      `Questions for "${topic}" can't be generated right now. Please try again in a moment.`
    );
  }
  return shuffle(OFFLINE_QUESTION_BANK[bankTopic]).map((entry, index) => ({
    id: index + 1,
    question: entry.q,
    options: shuffle([entry.answer, ...entry.wrong]),
    correctAnswer: entry.answer,
    explanation: entry.why,
  }));
};

const offlineResponse = (topic: string, level: number): QuizResponse => ({
  topic,
  level,
  source: 'offline',
  questions: getOfflineQuestions(topic),
});

// The quiz UI renders plain text, so drop Markdown code fences but keep the code
// and its line breaks.
const stripCodeFences = (text: string): string => text.replace(/```[\w+-]*\n?/g, '').trim();

// Keeps only well-formed questions: 4 distinct non-empty options and a correct
// answer that exactly matches one of them. Options are shuffled because models
// tend to put the correct answer first.
const sanitizeQuestions = (raw: unknown): QuizQuestion[] => {
  if (!Array.isArray(raw)) return [];
  const valid: QuizQuestion[] = [];
  for (const q of raw as any[]) {
    const question = typeof q?.question === 'string' ? stripCodeFences(q.question) : '';
    const options: string[] = Array.isArray(q?.options)
      ? q.options.map((o: unknown) => String(o).trim()).filter(Boolean)
      : [];
    // Prefer the index (unambiguous); fall back to the answer text
    const correctAnswer =
      Number.isInteger(q?.correctIndex) && q.correctIndex >= 0 && q.correctIndex < options.length
        ? options[q.correctIndex]
        : typeof q?.correctAnswer === 'string'
          ? q.correctAnswer.trim()
          : '';
    if (!question || options.length !== 4 || new Set(options).size !== 4 || !options.includes(correctAnswer)) {
      continue;
    }
    valid.push({
      id: valid.length + 1,
      question,
      options: shuffle(options),
      correctAnswer,
      explanation:
        typeof q?.explanation === 'string' && q.explanation.trim()
          ? q.explanation.trim()
          : 'Refer to fundamental computer science principles for details.',
    });
  }
  return valid;
};

export const generateQuizQuestions = async (topic: string, level: number): Promise<QuizResponse> => {
  const apiKey = process.env.GROQ_API_KEY;

  if (!apiKey || apiKey === 'your_groq_api_key' || apiKey.trim() === '') {
    console.warn(`[GroqQuizService] No valid GROQ_API_KEY found. Serving offline questions for "${topic}".`);
    return offlineResponse(topic, level);
  }

  const groq = new Groq({ apiKey });
  const levelText = level === 1 ? 'Easy' : level === 2 ? 'Medium' : 'Hard';

  const systemPrompt = `You are a Senior Computer Science Educator and technical interviewer. Generate exactly 10 multiple-choice questions for a quiz on the specified topic and difficulty level. Output STRICT JSON only.`;

  const userPrompt = `Generate a 10-question multiple choice quiz for the topic "${topic}" at level ${level} (${levelText}).
Return ONLY a valid JSON object matching this schema:
{
  "questions": [
    {
      "id": 1,
      "question": "Question text here",
      "options": ["Option A", "Option B", "Option C", "Option D"],
      "correctIndex": 0,
      "explanation": "Why the correct option is right."
    }
  ]
}

Ensure:
1. Exactly 10 questions in the array.
2. "options" contains 4 distinct choices.
3. "correctIndex" is the 0-based index (0-3) of the single correct option.
4. "explanation" gives clear technical reasoning in 1-2 sentences.
5. Questions are factually accurate and unambiguous.
6. Use plain text only, no Markdown. If a question includes code, put it on its own lines without code fences.`;

  for (const model of getModels()) {
    try {
      const completion = await groq.chat.completions.create({
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt },
        ],
        model,
        response_format: { type: 'json_object' },
        temperature: 0.7,
        // gpt-oss models reason before answering; low effort keeps latency and token usage down
        ...(model.startsWith('openai/gpt-oss') ? { reasoning_effort: 'low' as const } : {}),
      });

      const content = completion.choices[0]?.message?.content;
      if (!content) {
        console.warn(`[GroqQuizService] ${model} returned an empty response.`);
        continue;
      }

      const questions = sanitizeQuestions(JSON.parse(content).questions);
      if (questions.length >= 10) {
        return { topic, level, source: 'ai', questions: questions.slice(0, 10) };
      }
      console.warn(`[GroqQuizService] ${model} returned only ${questions.length} valid questions.`);
    } catch (err: any) {
      console.warn(`[GroqQuizService] ${model} failed:`, err?.message || err);
    }
  }

  console.warn(`[GroqQuizService] AI generation failed for all models. Serving offline questions for "${topic}".`);
  return offlineResponse(topic, level);
};
